import React, { createContext, useState, useContext, useEffect } from 'react';
import { useModal } from './ModalContext';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const { showModal } = useModal();

  // Состояния
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [orders, setOrders] = useState([]);

  // Загрузка данных при монтировании
  useEffect(() => {
    try {
      const savedUser = localStorage.getItem('user');
      const savedCart = localStorage.getItem('cart');
      const savedFavorites = localStorage.getItem('favorites');
      const savedOrders = localStorage.getItem('orders');

      if (savedUser) setUser(JSON.parse(savedUser));
      if (savedCart) setCart(JSON.parse(savedCart));
      if (savedFavorites) setFavorites(JSON.parse(savedFavorites));
      if (savedOrders) setOrders(JSON.parse(savedOrders));

    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  }, []);

  // Сохранение данных при изменении
  useEffect(() => {
    if (user) localStorage.setItem('user', JSON.stringify(user));
  }, [user]);

  useEffect(() => {
    localStorage.setItem('cart', JSON.stringify(cart));
  }, [cart]);

  useEffect(() => {
    localStorage.setItem('favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    localStorage.setItem('orders', JSON.stringify(orders));
  }, [orders]);

  // 🔐 РЕГИСТРАЦИЯ
  const register = async (username, email, password) => {
    try {
      setLoading(true);

      // Проверяем существующих пользователей
      const existingUsers = JSON.parse(localStorage.getItem('registeredUsers') || '[]');

      // Проверка email
      if (existingUsers.some(u => u.email === email)) {
        throw new Error('Пользователь с таким email уже существует');
      }

      // Создаем пользователя
      const newUser = {
        id: `user_${Date.now()}`,
        username,
        email,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      // Сохраняем в базу пользователей (с паролем)
      const userWithPassword = { ...newUser, password };
      const updatedUsers = [...existingUsers, userWithPassword];
      localStorage.setItem('registeredUsers', JSON.stringify(updatedUsers));

      // Устанавливаем пользователя (без пароля)
      setUser(newUser);

      showModal('success', null, 'Регистрация успешна!', `Добро пожаловать, ${username}!`);

      return newUser;

    } catch (error) {
      console.error('Registration error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // 🔑 ВХОД
  const login = async (email, password) => {
    try {
      setLoading(true);

      const existingUsers = JSON.parse(localStorage.getItem('registeredUsers') || '[]');
      const userData = existingUsers.find(u => u.email === email);

      if (!userData) {
        throw new Error('Пользователь с таким email не найден');
      }

      if (userData.password !== password) {
        throw new Error('Неверный пароль');
      }

      // Убираем пароль из данных пользователя
      const { password: _, ...userWithoutPassword } = userData;

      setUser(userWithoutPassword);

      return userWithoutPassword;

    } catch (error) {
      console.error('Login error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // 🚪 ВЫХОД
  const logout = () => {
    setUser(null);
    setCart([]);
    setFavorites([]);
    setOrders([]);

    // Очищаем localStorage
    localStorage.removeItem('user');
    localStorage.removeItem('cart');
    localStorage.removeItem('favorites');
    localStorage.removeItem('orders');
  };

  // 🛒 Функции для корзины
  const addToCart = (product) => {
    const existingItem = cart.find(item => item.id === product.id);
    let newCart;

    if (existingItem) {
      newCart = cart.map(item =>
        item.id === product.id
          ? { ...item, quantity: (item.quantity || 1) + 1 }
          : item
      );
    } else {
      newCart = [...cart, { ...product, quantity: 1 }];
    }

    setCart(newCart);
    return newCart;
  };

  const removeFromCart = (productId) => {
    const newCart = cart.filter(item => item.id !== productId);
    setCart(newCart);
    return newCart;
  };

  const updateCartQuantity = (productId, quantity) => {
    if (quantity < 1) {
      return removeFromCart(productId);
    }

    const newCart = cart.map(item =>
      item.id === productId ? { ...item, quantity } : item
    );
    setCart(newCart);
    return newCart;
  };

  // ❤️ Функции для избранного
  const addToFavorites = (product) => {
    if (favorites.some(item => item.id === product.id)) {
      return favorites;
    }

    const newFavorites = [...favorites, product];
    setFavorites(newFavorites);
    return newFavorites;
  };

  const removeFromFavorites = (productId) => {
    const newFavorites = favorites.filter(item => item.id !== productId);
    setFavorites(newFavorites);
    return newFavorites;
  };

  // 📦 Функции для заказов
  const createOrder = (orderData) => {
    const newOrder = {
      id: `ORD-${Date.now()}`,
      userId: user?.id,
      items: [...cart],
      total: cart.reduce((sum, item) => sum + (item.price || 0) * (item.quantity || 1), 0),
      date: new Date().toLocaleString('ru-RU'),
      status: 'pending',
      address: orderData.address,
      cardNumber: orderData.cardNumber ? `**** ${orderData.cardNumber.slice(-4)}` : 'Оплата при получении',
    };

    const newOrders = [newOrder, ...orders];
    setOrders(newOrders);

    // Очищаем корзину
    setCart([]);

    return newOrder;
  };

  const cancelOrder = (orderId) => {
    const newOrders = orders.map(order =>
      order.id === orderId ? { ...order, status: 'cancelled' } : order
    );
    setOrders(newOrders);
    return newOrders;
  };

  // 📊 Проверка авторизации
  const isAuthenticated = !!user;

  const value = {
    // Состояния
    user,
    loading,
    cart,
    favorites,
    orders,

    // Аутентификация
    register,
    login,
    logout,
    isAuthenticated,

    // Корзина
    addToCart,
    removeFromCart,
    updateCartQuantity,

    // Избранное
    addToFavorites,
    removeFromFavorites,

    // Заказы
    createOrder,
    cancelOrder,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
